<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$act=$_POST['act']??'';if($act==='status')db()->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=? AND role='student'")->execute([$id]);if($act==='delete')db()->prepare("DELETE FROM users WHERE id=? AND role='student'")->execute([$id]);flash('success','Student record updated.');go('students.php');}$term=trim($_GET['q']??'');$q=db()->prepare("SELECT u.id,u.name,u.email,u.status,u.created_at,p.course,p.college FROM users u JOIN student_profiles p ON p.user_id=u.id WHERE u.role='student' AND (u.name LIKE ? OR u.email LIKE ? OR p.course LIKE ?) ORDER BY u.created_at DESC LIMIT 200");$q->execute(["%$term%","%$term%","%$term%"]);page_start('Students',true); ?><div class="card mb-3"><div class="card-body"><form class="d-flex gap-2"><input class="form-control" name="q" placeholder="Search name, email, or course" value="<?= e($term) ?>"><button class="btn btn-primary">Search</button></form></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Course / College</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($q as $s): ?><tr><td><strong><?= e($s['name']) ?></strong><div class="small text-secondary"><?= e($s['email']) ?></div></td><td><?= e($s['course']) ?><div class="small text-secondary"><?= e($s['college']) ?></div></td><td><span class="status"><?= e($s['status']) ?></span></td><td><?= e(substr($s['created_at'],0,10)) ?></td><td><a class="btn btn-sm btn-outline-primary" href="../student/profile.php?id=<?= $s['id'] ?>">Profile</a><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= $s['id'] ?>"><input type="hidden" name="act" value="status"><button class="btn btn-sm btn-outline-secondary">Toggle</button></form><form method="post" class="d-inline" data-confirm="Permanently delete this student and related data?"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="id" value="<?= $s['id'] ?>"><input type="hidden" name="act" value="delete"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach ?></tbody></table></div></div><?php page_end(); ?>
